I think you can see pkg/component-261/device-manager/generic_device.go Start function and healthCheck function. I think  `dpi.initialized` is set to `false`, when kubelet restarts. 

First, Kubelet will rebuild the `/var/lib/kubelet/device-plugins` dir when kubelet is restarted. Next, the `healthCheck` function watch the socket file(socketPath is `/var/lib/kubelet/device-plugins/proj-${deviceName}.sock`) changes and return nil. Then, the `Start` function executes `defer dpi.Stop()`. Finally, `dpi.initialized` is set to `false`.

```go
// pkg/component-261/device-manager/generic_device.go
func (dpi *GenericDevicePlugin) healthCheck() error {
	...
	dirName = filepath.Dir(dpi.socketPath)
	err = watcher.Add(dirName)

	if err != nil {
		return fmt.Errorf("failed to add the device-plugin kubelet path to the watcher: %v", err)
	}
        // socketPath is /var/lib/kubelet/device-plugins/proj-${deviceName}.sock
	_, err = os.Stat(dpi.socketPath)
	if err != nil {
		return fmt.Errorf("failed to stat the device-plugin socket: %v", err)
	}

	for {
		select {
		case <-dpi.stop:
			return nil
		case err := <-watcher.Errors:
			logger.Reason(err).Errorf("error watching devices and device plugin directory")
		case event := <-watcher.Events:
			logger.V(4).Infof("health Event: %v", event)
			if event.Name == devicePath {
				// Health in this case is if the device path actually exists
				if event.Op == fsnotify.Create {
					logger.Infof("monitored device %s appeared", dpi.deviceName)
					dpi.health <- pluginapi.Healthy
				} else if (event.Op == fsnotify.Remove) || (event.Op == fsnotify.Rename) {
					logger.Infof("monitored device %s disappeared", dpi.deviceName)
					dpi.health <- pluginapi.Unhealthy
				}
			} else if event.Name == dpi.socketPath && event.Op == fsnotify.Remove {
				logger.Infof("device socket file for device %s was removed, kubelet probably restarted.", dpi.deviceName)
				return nil
			}
		}
	}
}
// Start starts the device plugin
func (dpi *GenericDevicePlugin) Start(stop chan struct{}) (err error) {
	...
	defer dpi.Stop()
	...
	go func() {
		errChan <- dpi.healthCheck()
	}()

	dpi.setInitialized(true)
	logger.Infof("%s device plugin started", dpi.deviceName)
	err = <-errChan

	return err
}
// Stop stops the gRPC server
func (dpi *GenericDevicePlugin) Stop() error {
	defer func() {
		if !IsChanClosed(dpi.done) {
			close(dpi.done)
		}
	}()
	dpi.server.Stop()
	dpi.setInitialized(false)
	return dpi.cleanup()
}
```
If virt-handler executes a **heartbeat** at this time, the node `host-215.example/schedulable` label value will be set to `false`.
```go
// pkg/component-261/device-manager/device_controller.go
func (c *DeviceController) Initialized() bool {
	c.startedPluginsMutex.Lock()
	defer c.startedPluginsMutex.Unlock()
	for _, dev := range c.startedPlugins {
		if !dev.devicePlugin.GetInitialized() {
			return false
		}
	}

	return true
}

// pkg/component-261/heartbeat/heartbeat.go
func (h *HeartBeat) do() {
	...
	projSchedulable := "true"
	if !h.deviceManagerController.Initialized() {
		projSchedulable = "false"
	}

	var data []byte
	// Label the node if cpu manager is running on it
	// This is a temporary workaround until k8s bug #60235 is resolved
	cpuManagerEnabled := false
	if h.clusterConfig.CPUManagerEnabled() {
		cpuManagerEnabled = h.isCPUManagerEnabled(h.cpuManagerPaths)
	}
	data = []byte(fmt.Sprintf(`{"metadata": { "labels": {"%s": "%s", "%s": "%t"}, "annotations": {"%s": %s}}}`,
		v1.NodeSchedulable, projSchedulable,
		v1.CPUManager, cpuManagerEnabled,
		v1.VirtHandlerHeartbeat, string(now),
	))
	_, err = h.clientset.Nodes().Patch(context.Background(), h.host, types.StrategicMergePatchType, data, metav1.PatchOptions{})
	if err != nil {
		log.DefaultLogger().Reason(err).Errorf("Can't patch node %s", h.host)
		return
	}
        ...
}
```
After kubelet restarts, kubelet will **kill pods** that do not match the node label.（virt-launcher pod nodeSelector is `host-215.example/schedulable: "true"`）At this time, the node `host-215.example/schedulable` label value is `false`.The virt-launcher pod will be killed by kubelet, causing the vm to restart.

Some issues about kubelet behavior:
https://host-623.example/kubernetes/kubernetes/issues/57355
https://host-623.example/kubernetes/kubernetes/issues/70654
